// The day's affirmation in German, for the country pages in German. Written by scripts/home_extras.py from data/affirmations-i18n/; do not edit.
(function(){var D=document;if(D.getElementById("affirmations-local"))return;var e=D.createElement("script");e.type="application/json";e.id="affirmations-local";e.textContent="[\"Du musst heute nicht alles schaffen. Der nächste kleine Schritt reicht.\", \"Müde sein heisst nicht versagen. Du bist müde, weil du jeden Tag wieder da bist.\", \"Der Abwasch kann warten. Du darfst dich fünf Minuten hinsetzen.\", \"Müsli zum Abendessen zählt auch als Familie versorgen.\", \"Ruhe musst du dir nicht verdienen. Du darfst dich jetzt gleich ausruhen.\", \"Manchmal ist der Sieg, dass alle es bis zum Schlafengehen geschafft haben. Das ist ein echter Sieg.\", \"Du leistest mehr, als irgendjemand sieht. Ich sehe es.\", \"Ein unordentliches Zuhause und geliebte Kinder. Das ist ein guter Tausch.\", \"An einem schweren Tag sieht dein Bestes anders aus, und es zählt trotzdem.\", \"Einmal tief durchatmen. Schultern runter. Du machst das gut.\", \"Heute darfst du die Messlatte tiefer legen. Höher legen kannst du sie an einem anderen Tag.\", \"Um Hilfe zu bitten ist stark, nicht schwach.\", \"Du darfst Nein sagen, wenn noch eine Sache dazukommen soll.\", \"Wenn du dich heute einsam gefühlt hast: Du bist nicht die einzige Mama, der es so geht. Wir sind viele.\", \"Du hast eine Freundin verdient, die fragt, wie es dir geht, und auf die Antwort wartet.\", \"Es ist okay, dich als Erste zu melden. Die meisten Mamas hoffen, dass es jemand tut.\", \"Sich übersehen zu fühlen heisst nicht, dass du nicht zählst. Du bist sehr wichtig.\", \"Deine Gefühle ergeben Sinn. Du bist nicht zu viel.\", \"Hier musst du deinen schweren Tag nicht erklären. Wir verstehen dich.\", \"Eine Nachricht an eine andere Mama mit „Geht mir auch so“ kann den ganzen Tag drehen.\", \"Füttern, wickeln, wiegen, von vorn. Das ist echte Arbeit, auch wenn es nach Stillsitzen aussieht.\", \"Du und dein Baby lernt euch noch kennen. Es gibt keine Eile.\", \"Die Tage mit einem Neugeborenen sind lang. Diese Zeit dauert nicht ewig.\", \"Wenn du heute nur einen kleinen Menschen satt und warm gehalten hast, hast du viel geleistet.\", \"Du musst nicht schnell wieder die Alte sein. Du darfst einfach da sein, wo du gerade bist.\", \"Wie auch immer dein Baby gefüttert wird: Du sorgst für dein Baby. Das zählt.\", \"Du kannst zu wenig Schlaf haben und trotzdem voller Liebe sein.\", \"Halt das Baby und lass den Haushalt liegen. Der Haushalt läuft dir nicht weg.\", \"Ein Wutanfall im Supermarkt macht dich nicht zur schlechten Mutter. Es heisst nur, dass du ein Kleinkind hast.\", \"Die Kleinen testen Grenzen, weil sie sich bei dir sicher fühlen.\", \"Du bist heute eine Minute länger ruhig geblieben als gestern. Das zählt.\", \"Wenn dir der Kragen geplatzt ist, macht eine Umarmung und ein „Tut mir leid“ vieles wieder gut. Und es lehrt sie etwas Gutes.\", \"Klebrige Hände, laute Stimmen, grosse Gefühle. Du ziehst einen ganzen Menschen gross.\", \"Das fünfte „Warum?“ in dieser Stunde ist ein kleiner Kopf, der wächst.\", \"Für eine schöne Erinnerung braucht es keinen perfekten Tag.\", \"Eine zugeknallte Tür ist nicht das Ende der Geschichte. Lass das Licht an.\", \"Dein Teenager sagt es vielleicht nicht, aber dass du verlässlich da bist, ist wichtig.\", \"Der ruhige Pol im Haus zu sein ist harte Arbeit. Du schaffst es.\", \"Manche der besten Gespräche passieren im Auto. Fahr ruhig weiter.\", \"Sie lösen sich, um erwachsen zu werden, nicht um dich zurückzulassen.\", \"Du musst nicht auf alles eine Antwort haben. Zuhören ist schon ein grosser Teil.\", \"Grosse Kinder brauchen dich immer noch, nur auf leisere Art.\", \"Es allein zu stemmen braucht eine Kraft, die die meisten nie sehen.\", \"Du bist genug Mama für dein Kind. Das warst du schon immer.\", \"Zwei Hände, hundert Aufgaben. Sei nachsichtig mit dir.\", \"Deine Kinder lernen von dir, wie ein starker, liebevoller Mensch aussieht.\", \"Eine Pause heisst nicht, deinen Posten zu verlassen. So hältst du durch.\", \"Niemand führt Buch. Liebe und Dasein sind das, was zählt.\", \"Trauer und Liebe kommen aus derselben Quelle. Wie sehr du jemanden vermisst, zeigt, wie sehr du geliebt hast.\", \"Es gibt keinen richtigen Zeitplan für Trauer. Nimm dir die Zeit, die du brauchst.\", \"An schweren Jahrestagen sei so sanft mit dir, wie du es mit einer Freundin wärst.\", \"Du kannst traurig sein und trotzdem mit deinen Kindern lachen. Beides ist echt.\", \"Wenn du eine Schwangerschaft oder ein Baby verloren hast, ist dieser Verlust echt, und deine Liebe auch.\", \"An manchen Tagen ist die Trauer leise, an anderen laut. Beides ist in Ordnung.\", \"Wenig Geld heisst nicht wenig Liebe.\", \"Deine Kinder werden sich eher an die Zeit mit dir erinnern als an die Dinge, die du gekauft hast.\", \"Nach Hilfe bei den Rechnungen zu fragen ist klug, nicht beschämend. Genau dafür gibt es sie.\", \"Ein kostenloser Nachmittag im Park kann der schönste Tag der Woche sein.\", \"Du hast das Geld noch eine Woche länger gestreckt. Das ist eine echte Kunst.\", \"Geldsorgen machen müde. Du trägst viel, und du bist immer noch da.\", \"Du hast heute ein Glas Wasser getrunken. Fang da an.\", \"Alle sind aus dem Haus gekommen. Vielleicht passten die Schuhe nicht zusammen. Trotzdem ein Sieg.\", \"Du hast den Anruf gemacht, vor dem dir gegraut hat. Das war mutig.\", \"Du hast heute gelacht. Halt das fest.\", \"Ein warmes Essen, ein sauberes Shirt, eine Gutenachtgeschichte. Kleine Dinge ergeben zusammen eine Kindheit.\", \"Heute warst du freundlich zu jemandem, und sei es nur zu dir selbst.\", \"Fortschritt, nicht Perfektion. Du bist heute vorangekommen.\", \"Du hast eine Sache auf der Liste erledigt. Das ist eine mehr als keine.\", \"Du bist eine gute Mama. Dass du dir darüber Gedanken machst, zeigt, wie viel dir daran liegt.\", \"Du bist mehr als das, was du an einem Tag schaffst.\", \"Deine Kinder brauchen keine perfekte Mama. Sie brauchen dich, und sie haben dich.\", \"Sei mit dir so geduldig, wie du es mit deinen Kindern bist.\", \"Du darfst Raum einnehmen, Wünsche haben und deine eigenen Träume.\", \"Ein Fehler hebt die Liebe nicht auf. Morgen ist ein neuer Anfang.\", \"Du bist für jemanden die ganze Welt, und du bist auch ein eigener Mensch.\", \"Es ist okay, nicht jede Minute zu geniessen. Du kannst deine Kinder trotzdem von ganzem Herzen lieben.\", \"Es gibt nicht den einen richtigen Weg, Mama zu sein. Dein Weg ist erlaubt.\", \"Wie in der Baumhaltung darfst du wackeln. Du findest dein Gleichgewicht wieder.\", \"Stell deine Füsse fest auf den Boden wie in der Berghaltung. Du stehst sicherer, als es sich anfühlt.\", \"Krieger II: starke Beine, offene Arme. So gehst du diese Woche an.\", \"Atme auf vier ein und auf vier aus. Du bist genau hier, und du machst das gut.\", \"Mach dich weit wie ein Stern. Du darfst Raum einnehmen.\", \"Eine tiefe, breite Hocke zu halten ist schwer. Ein langer Tag auch. Du hältst ihn.\", \"Du kannst dich neigen wie eine Mondsichel und trotzdem stehen bleiben.\", \"Du musst noch nicht bis zu den Zehen kommen. Jedes bisschen Dehnung zählt.\", \"Dreieckshaltung: eine Hand unten, eine Hand oben. Bleib geerdet und streck dich weiter.\", \"Es ist spät. Was heute liegen geblieben ist, kann bis morgen warten.\", \"Um diese Uhrzeit mit dem Baby wach? Gerade sind ganz viele Mamas mit dir wach.\", \"Im Haus ist es still. Dieser Moment gehört dir. Atme.\", \"Du hast den Tag geschafft. Mehr brauchte der Tag nicht.\", \"Wenn dein Kopf heute Nacht keine Ruhe gibt, schreib es auf und lass es bis morgen warten.\", \"Schliess die Augen. Morgen darfst du neu anfangen.\", \"Feiertage können schwer und schön zugleich sein. Wie sich diese Zeit für dich auch anfühlt, es ist okay.\", \"Der Tisch muss nicht perfekt sein. Die Menschen darum herum sind das, was zählt.\", \"Wenn dir dieses Jahr jemand am Tisch fehlt, sei behutsam mit deinem Herzen.\", \"Danke, Mama, für jedes Essen, jede Fahrt und jede Umarmung.\", \"Du musst nicht Gastgeberin sein, backen oder die ganze Zeit lächeln. Ein einfaches Fest ist immer noch ein Fest.\", \"Das schönste Geschenk für deine Kinder in diesem Jahr ist Zeit mit dir.\", \"Ein kleines Fest ist trotzdem voller Liebe. Es braucht nicht viel Geld, um es besonders zu machen.\", \"Kalte Tage, warme Umarmungen. Du bist der warme Ort in deinem Zuhause.\", \"Es ist okay, beim Festtagstrubel nicht überall mitzumachen. Frieden ist auch ein Geschenk.\", \"Wenn diese Zeit dir dieses Jahr schwer wird, bist du nicht allein. Nimm einen Tag nach dem anderen.\"]";D.body.appendChild(e)})();
